<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

use Civi\Lughauth\Features\OAuth\Profile\Domain\ConsentedClient;

class ConsentedScopesPanel
{
    /**
     * @param ConsentedClient[] $consents
     */
    public function render(
        array $consents,
        string $revokeBaseUrl,
        string $cancelUrl,
        ?string $successMessage,
        array $t = [],
    ): string {
        $html = '<h1>' . ($t['title'] ?? 'Consented scopes') . '</h1>';

        if ($successMessage !== null && $successMessage !== '') {
            $html .= '<p class="success">' . htmlspecialchars($successMessage) . '</p>';
        }

        $html .= '<p>' . ($t['help'] ?? '') . '</p>';

        if ($consents === []) {
            $html .= '<p>' . ($t['empty'] ?? 'No consents found.') . '</p>';
        } else {
            $unknownLabel = $t['unknown'] ?? 'Unknown';
            $grantedAtLabel = htmlspecialchars($t['grantedAt'] ?? 'Granted on');
            $revokeLabel = htmlspecialchars($t['revoke'] ?? 'Revoke all');
            $revokeScopeLabel = htmlspecialchars($t['revokeScope'] ?? 'Revoke');

            foreach ($consents as $consent) {
                $name = htmlspecialchars($consent->clientName !== '' ? $consent->clientName : $consent->clientId);
                $grantedAt = $consent->grantedAt !== null
                    ? htmlspecialchars($consent->grantedAt->format('Y-m-d H:i'))
                    : htmlspecialchars($unknownLabel);
                $revokeClientUrl = htmlspecialchars($revokeBaseUrl . '/' . $consent->consentUid);
                $revokeScopeUrl = htmlspecialchars($revokeBaseUrl . '/' . $consent->consentUid . '/scope');

                $html .= '<div class="consent-client-card">'
                    . '<div class="consent-client-header"><div>'
                    . '<div class="consent-client-name">' . $name . '</div>'
                    . '<div class="consent-client-meta">' . $grantedAtLabel . ': ' . $grantedAt . '</div>'
                    . '</div>'
                    . '<form method="POST" action="' . $revokeClientUrl . '" style="display:inline">'
                    . '<input class="link-button" type="submit" value="' . $revokeLabel . '" />'
                    . '</form>'
                    . '</div>';

                $scopes = array_filter(explode(' ', $consent->scopes), fn($s) => trim($s) !== '');
                $html .= '<ul class="scopes-list">';
                foreach ($scopes as $scope) {
                    $scopeEsc = htmlspecialchars($scope);
                    $html .= '<li class="scope-item">'
                        . '<span class="scope-tag">' . $scopeEsc . '</span>'
                        . '<form method="POST" action="' . $revokeScopeUrl . '" style="display:inline;">'
                        . '<input type="hidden" name="scope" value="' . $scopeEsc . '" />'
                        . '<input class="link-button" type="submit" value="' . $revokeScopeLabel . '" />'
                        . '</form>'
                        . '</li>';
                }
                $html .= '</ul></div>';
            }
        }

        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $cancelUrl = htmlspecialchars($cancelUrl);
        $html .= '<div class="profile-actions"><a class="secondary-button" href="' . $cancelUrl . '">'
            . $backLabel . '</a></div>';

        return $html;
    }
}
